import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_svg/flutter_svg.dart';

/// One piece of bundled clip art.
///
/// The art itself is an SVG on disk, generated by `tool/generate_clipart.py`.
/// Nothing here describes how it looks — that is the file's job — because a
/// catalog that also carried colours would be a second, silently divergent
/// copy of the drawing.
class Sticker {
  const Sticker({
    required this.id,
    required this.name,
    required this.category,
    required this.asset,
    required this.tintable,
  });

  final String id;

  /// What the picker calls it.
  final String name;

  /// The tab it sits under. Free text rather than an enum: the pack is data,
  /// and adding a category should not need a code change.
  final String category;

  /// Bundle path of the SVG.
  final String asset;

  /// Whether the whole sticker may be recoloured.
  ///
  /// True only for art drawn in ONE colour. Recolouring a speech bubble would
  /// set its fill and its outline to the same value and erase the drawing, so
  /// multi-colour art declares itself off-limits here rather than leaving the
  /// editor to guess from the file.
  final bool tintable;

  factory Sticker.fromJson(Map<String, dynamic> json) => Sticker(
    id: json['id'] as String,
    name: json['name'] as String,
    category: json['category'] as String,
    asset: json['asset'] as String,
    tintable: json['tintable'] as bool? ?? false,
  );
}

/// The bundled clip-art pack, grouped the way the picker shows it.
class ClipartCatalog {
  const ClipartCatalog(this.stickers);

  final List<Sticker> stickers;

  /// Categories in the order the manifest lists them, not alphabetical: the
  /// generator emits them in a deliberate order — the useful ones first — and
  /// sorting here would throw that away.
  List<String> get categories {
    final seen = <String>[];
    for (final sticker in stickers) {
      if (!seen.contains(sticker.category)) seen.add(sticker.category);
    }
    return seen;
  }

  List<Sticker> inCategory(String category) =>
      stickers.where((s) => s.category == category).toList();

  Sticker? byId(String id) {
    for (final sticker in stickers) {
      if (sticker.id == id) return sticker;
    }
    // Null rather than a fallback sticker. A missing id means a project made
    // with a later pack than this build ships, and quietly substituting some
    // other drawing would be worse than leaving a gap the caller can skip.
    return null;
  }

  factory ClipartCatalog.fromJson(Map<String, dynamic> json) => ClipartCatalog([
    for (final s in (json['stickers'] as List? ?? const []))
      Sticker.fromJson(s as Map<String, dynamic>),
  ]);
}

Future<ClipartCatalog> loadClipartCatalog() async {
  final raw = await rootBundle.loadString('assets/clipart/manifest.json');
  return ClipartCatalog.fromJson(jsonDecode(raw) as Map<String, dynamic>);
}

final clipartCatalogProvider = FutureProvider<ClipartCatalog>(
  (ref) => loadClipartCatalog(),
);

/// The sticker's art as a picture, ready to draw on any canvas.
///
/// `vg.loadPicture` is flutter_svg's own headless path — it re-exports `vg`
/// from `package:vector_graphics` — and headless is the requirement: the
/// retoucher composites through a bare `PictureRecorder` with no widget tree to
/// hang an `SvgPicture` on. Same reason `ScreenshotComposer` redraws the image
/// through a blur rather than reaching for a `BackdropFilter`.
///
/// A picture rather than a rasterisation, so the art stays crisp at 12x zoom
/// and at full export resolution from one record — which is the whole point of
/// the pack shipping as SVG. And not through `SvgImport`, which deliberately
/// collapses a file to a single filled outline: two thirds of these stickers
/// are multi-path and multi-colour, and that would erase them.
///
/// The caller owns the result and must dispose it exactly once.
/// [PictureInfo.size] is the SVG's own viewBox, which the caller needs in order
/// to scale the art into its box without stretching it.
Future<PictureInfo> loadStickerPicture(Sticker sticker) =>
    vg.loadPicture(SvgAssetLoader(sticker.asset), null);
